<?php
$totals=['employees'=>0,'gross'=>0,'deductions'=>0,'net'=>0,'exceptions'=>0,'published'=>0];$pipeline=['Draft'=>0,'Review'=>0,'Confirmed'=>0,'Paid'=>0];
foreach($runs as $run){foreach($totals as $key=>$value)$totals[$key]+=(int)$run[$key];$stage=match($run['status']){'Paid'=>'Paid','Finalized','Locked'=>'Confirmed','Draft'=>'Draft',default=>'Review'};$pipeline[$stage]+=(int)$run['employees'];}
$q=$pdo->prepare('SELECT e.snapshot,e.net FROM hr_payroll_entries e JOIN hr_payroll_runs r ON r.id=e.run_id WHERE r.month=?');$q->execute([$month]);$departments=[];$deductionParts=[];$earners=[];$bands=['Under 20,000'=>0,'20,000–30,000'=>0,'30,000–40,000'=>0,'40,000–50,000'=>0,'50,000+'=>0];
foreach($q as $entry){$s=json_decode($entry['snapshot'],true);if(!isset($s['employee']))continue;$net=(int)$entry['net'];$department=$s['employee']['department_name']??'Unassigned';$departments[$department]=($departments[$department]??0)+$net;$earners[]=['name'=>$s['employee']['name']??'Employee','code'=>$s['employee']['employee_code']??'','net'=>$net];$band=$net<2000000?'Under 20,000':($net<3000000?'20,000–30,000':($net<4000000?'30,000–40,000':($net<5000000?'40,000–50,000':'50,000+')));$bands[$band]++;foreach($s['components']??[] as $c)if($c['category']==='Deduction'){$key=$c['name']??$c['code'];$deductionParts[$key]=($deductionParts[$key]??0)+(int)$c['amount'];}}
arsort($departments);arsort($deductionParts);usort($earners,fn($a,$b)=>$b['net']<=>$a['net']);
$start=(new DateTimeImmutable($month.'-01'))->modify('-5 months');$q=$pdo->prepare("SELECT r.month,SUM(e.gross) gross,SUM(e.deductions) deductions,SUM(e.net) net FROM hr_payroll_runs r JOIN hr_payroll_entries e ON e.run_id=r.id WHERE r.month BETWEEN ? AND ? AND r.status IN ('Finalized','Paid') GROUP BY r.month ORDER BY r.month");$q->execute([$start->format('Y-m'),$month]);$trend=array_column($q->fetchAll(PDO::FETCH_ASSOC),null,'month');
function pay_visual_bars(array $values,bool $money=true):void{$max=max(array_merge([1],array_values($values)));if(!$values){echo '<div class="pay-empty">No calculated data for this month.</div>';return;}echo '<div class="pay-bars">';foreach($values as $label=>$amount)echo '<div class="pay-bar-row"><div><span>'.h($label).'</span><strong>'.($money?pay_amount((int)$amount):(int)$amount).'</strong></div><div class="pay-bar-track"><span style="width:'.max(0,round($amount/$max*100,2)).'%"></span></div></div>';echo '</div>';}
?>
<section class="pay-kpis" aria-label="Payroll summary">
<?php foreach(['Net payroll'=>['net','Amount after deductions'],'Gross pay'=>['gross','Total earnings'],'Deductions'=>['deductions','Configured deductions'],'Employees'=>['employees','Payroll entries this month'],'Published payslips'=>['published','Available to employees'],'Needs attention'=>['exceptions','Entries with exceptions']] as $label=>[$key,$hint]):?><article class="card pay-kpi"><span class="pay-kpi-icon" aria-hidden="true"><?=in_array($key,['gross','net','deductions'],true)?'₹':'▤'?></span><span class="pay-kpi-label"><?=h($label)?></span><strong><?=in_array($key,['gross','net','deductions'],true)?pay_amount($totals[$key]):$totals[$key]?></strong><small><?=h($hint)?></small></article><?php endforeach;?></section>
<p class="pay-muted">Selected month: <?=h($month)?>. Current-month totals include provisional calculations; trend includes finalized and paid payroll only.</p>
<div class="pay-dashboard-layout"><div class="pay-dashboard-main">
<section class="card pay-panel"><h2>Payslip pipeline</h2><p class="pay-muted">Employee entries grouped by payroll run stage</p><div class="pay-pipeline"><?php foreach($pipeline as $stage=>$count):?><div class="pay-stage pay-stage-<?=strtolower($stage)?>"><strong><?=$count?></strong><span><?=h($stage)?></span></div><?php endforeach;?></div></section>
<section class="card pay-panel"><div class="pay-panel-heading"><div><h2>Payroll cost trend</h2><p class="pay-muted">Gross, deductions and net · last six months</p></div><div class="pay-legend"><span>● Gross</span><span>● Deductions</span><span>● Net</span></div></div>
<?php if(!$trend):?><div class="pay-empty">Your payroll trend will appear after a run is finalized.</div><?php else:
$maximum=1;foreach($trend as $row)foreach(['gross','deductions','net'] as $key)$maximum=max($maximum,(int)$row[$key]);$months=[];for($i=0;$i<6;$i++)$months[]=$start->modify('+'.$i.' months')->format('Y-m');?>
<svg class="pay-line-chart" viewBox="0 0 760 260" role="img" aria-label="Six-month finalized payroll cost trend; exact values in the table below">
<?php for($i=0;$i<5;$i++):$y=20+$i*45;?><line x1="75" y1="<?=$y?>" x2="735" y2="<?=$y?>" class="pay-chart-grid"/><text x="65" y="<?=$y+4?>" text-anchor="end"><?=h(number_format(($maximum/100)*(1-$i/4),0))?></text><?php endfor;?>
<?php foreach(['gross'=>'#9f110c','deductions'=>'#bc7c22','net'=>'#217769'] as $key=>$color):$points=[];foreach($months as $i=>$m){if(!isset($trend[$m])){if(count($points)>1)echo '<polyline fill="none" stroke="'.$color.'" stroke-width="3" points="'.implode(' ',$points).'"/>';$points=[];continue;}$x=75+$i*132;$y=200-((int)$trend[$m][$key]/$maximum*180);$points[]=$x.','.$y;echo '<circle cx="'.$x.'" cy="'.$y.'" r="4" fill="'.$color.'"><title>'.h($m.' '.ucfirst($key).' '.pay_amount((int)$trend[$m][$key])).'</title></circle>';}if(count($points)>1)echo '<polyline fill="none" stroke="'.$color.'" stroke-width="3" points="'.implode(' ',$points).'"/>';endforeach;?>
<?php foreach($months as $i=>$m):?><text x="<?=75+$i*132?>" y="235" text-anchor="middle"><?=h(date('M Y',strtotime($m.'-01')))?></text><?php endforeach;?></svg>
<details><summary>View exact monthly amounts</summary><div class="pay-table"><table><thead><tr><th>Month</th><th>Gross</th><th>Deductions</th><th>Net</th></tr></thead><tbody><?php foreach($months as $m):?><tr><td><?=h($m)?></td><?php foreach(['gross','deductions','net'] as $key):?><td><?=isset($trend[$m])?pay_amount((int)$trend[$m][$key]):'No finalized run'?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></details><?php endif;?></section>
<div class="pay-dashboard-pair"><section class="card pay-panel"><h2>Cost by department</h2><p class="pay-muted">Net pay for <?=h($month)?></p><?php pay_visual_bars($departments);?></section><section class="card pay-panel"><h2>Salary distribution</h2><p class="pay-muted">Employee entries by monthly net pay band</p><?php if($earners)pay_visual_bars($bands,false);else echo '<div class="pay-empty">Calculate payroll to see salary distribution.</div>';?></section></div>
</div><div class="pay-dashboard-side"><?php if(can($pdo,$user,'payroll.salary.view')||can($pdo,$user,'payslip.view')):?><section class="card pay-panel"><h2>Top earners</h2><p class="pay-muted">Highest net pay · <?=h($month)?></p><?php foreach(array_slice($earners,0,5) as $i=>$person):?><div class="pay-earner"><span class="pay-avatar"><?=$i+1?></span><div><strong><?=h($person['name'])?></strong><small><?=h($person['code'])?></small></div><b><?=pay_amount($person['net'])?></b></div><?php endforeach;if(!$earners)echo '<div class="pay-empty">No calculated salaries yet.</div>';?></section><?php endif;?><section class="card pay-panel"><h2>Deduction components</h2><p class="pay-muted">Top components this month</p><?php pay_visual_bars(array_slice($deductionParts,0,6,true));?></section></div></div>
<?php
$q=$pdo->prepare("SELECT u.name,e.employee_code FROM employees e JOIN users u ON u.id=e.user_id WHERE e.deleted_at IS NULL AND e.employment_status='Active' AND u.active=1 AND NOT EXISTS(SELECT 1 FROM hr_salary_assignments s WHERE s.employee_id=e.user_id AND s.effective_from<=? AND (s.effective_to IS NULL OR s.effective_to>=?)) ORDER BY u.name");$q->execute([$month.'-01',$month.'-01']);$missing=$q->fetchAll(PDO::FETCH_ASSOC);?>
<details class="card pay-panel"><summary>Employees missing salary at month start <span class="pay-count"><?=count($missing)?></span></summary><?php if(!$missing):?><p class="pay-muted">No missing salary assignments.</p><?php else:?><ul><?php foreach($missing as $person):?><li><?=h($person['name'].' · '.$person['employee_code'])?></li><?php endforeach;?></ul><?php endif;?></details>
